fn copyto<T: Copy>(dst: Vec<T>, src: Vec<T>, mask: Vec<bool>) -> Vec<T> {
    let n = dst.len();
    debug_assert_eq!(src.len(), n, "src and dst must have the same length");
    debug_assert_eq!(mask.len(), n, "mask must have the same length as dst and src");

    let mut result = Vec::with_capacity(n);
    for i in 0..n {
        if mask[i] {
            // mask true → take from src
            result.push(src[i]);
        } else {
            // mask false → take from dst
            result.push(dst[i]);
        }
    }
    result
}